sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float brightness;
uniform float contrast;
uniform float highlights;
layout(color) uniform half4 color;
uniform float blend;
uniform float opacity;
uniform float outside;
uniform float falloff;
uniform float style;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    half4 g = blurred.eval(coord);
    float3 soft = falloff > 0.5 ? float3(g.rgb) : g.a > 0.0 ? float3(g.rgb) / float(g.a) : float3(0.0);
    float3 s;
    float k;
    if (style > 0.5) {
        float3 b = soft * pow(max(brightness, 0.0), 1.3);
        float l = luma(b);
        float3 m = mix(b, float3(l), clamp(0.145 - 0.113 * highlights + 0.525 * blend - 0.098 * l + 1.01 * highlights * l, 0.0, 1.0));
        s = clamp(m * (1.0 - contrast * (1.0 - m)), 0.0, 1.0) * mix(float3(1.0), float3(color.rgb), clamp((1.176 - 0.636 * highlights) * blend, 0.0, 1.0));
        k = max(s.r, max(s.g, s.b));
    } else {
        float l = clamp(((luma(soft) - 0.5) * (1.0 + contrast) + 0.5) * brightness, 0.0, 1.0);
        float w = mix(1.0, smoothstep(0.25, 1.0, l), clamp((highlights - 0.5) * 2.0, 0.0, 1.0));
        s = float3(l) * w * mix(float3(1.0), float3(color.rgb), clamp(blend, 0.0, 1.0));
        k = l * w;
    }
    s *= float(color.a) * clamp(opacity, 0.0, 1.0);
    float spill = (falloff > 0.5 ? 1.0 : float(g.a)) * (1.0 - float(c.a)) * clamp(outside, 0.0, 1.0);
    float a = float(c.a) + spill * k * float(color.a) * clamp(opacity, 0.0, 1.0);
    float3 rgb = float3(c.rgb) * (1.0 - s) + s * (float(c.a) + spill);
    return half4(half3(clamp(rgb, 0.0, a)), half(a));
}
